def is_valid_ipv4(s: str) -> bool:
    # No whitespace allowed
    if any(c.isspace() for c in s):
        return False
    parts = s.split('.')
    if len(parts) != 4:
        return False
    for part in parts:
        if not part or not part.isdigit():
            return False
        # No leading zeros unless the part is exactly "0"
        if len(part) > 1 and part[0] == '0':
            return False
        num = int(part)
        if num < 0 or num > 255:
            return False
    return True
```

