import re

def parse_duration(s: str) -> int:
    total = 0
    for value, unit in re.findall(r'(\d+)([hms])', s):
        if unit == 'h':
            total += int(value) * 3600
        elif unit == 'm':
            total += int(value) * 60
        elif unit == 's':
            total += int(value)
    return total
