def roman_to_int(s: str) -> int:
    mapping = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
    total = 0
    i = 0
    while i < len(s):
        if s[i] not in mapping:
            raise ValueError(f"Invalid Roman numeral character: {s[i]}")
        if i + 1 < len(s):
            if s[i + 1] not in mapping:
                raise ValueError(f"Invalid Roman numeral character: {s[i + 1]}")
            if mapping[s[i]] < mapping[s[i + 1]]:
                total += mapping[s[i + 1]] - mapping[s[i]]
                i += 2
                continue
        total += mapping[s[i]]
        i += 1
    if total > 3999:
        raise ValueError("Roman numeral value exceeds 3999")
    return total
```

